INSERT INTO "public"."mgh_neighborhoods" ("id", "label", "created_at", "short_desc_tr", "long_desc_tr", "images", "is_featured", "display_order", "walking_minutes_from_jemaa", "category_tags", "ambiance_tags", "latitude", "longitude", "city_id", "meta") VALUES ('agdal', '{"en":"⁠⁠Agdal","es":"⁠⁠Agdal","fr":"⁠⁠Agdal"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/7/78/Agdale_%28retouched%29.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('ait-ben-haddou', '{"en":"Aït Ben Haddou","es":"Aït Ben Haddou","fr":"Aït Ben Haddou"}', '2026-06-03 18:49:13.327169+00', '{"en":"A UNESCO-listed earthen ksar that has played the part of Jerusalem, Thebes and Westeros on screen.","es":"Un ksar de tierra Patrimonio de la UNESCO, escenario de Jerusalén, Tebas y Poniente en el cine.","fr":"Un ksar de terre classé à l''UNESCO, qui a tour à tour joué Jérusalem, Thèbes et Westeros à l''écran."}', '{"en":"Half an hour from Ouarzazate, the fortified village of Aït Ben Haddou rises out of the desert in stacked towers of pisé. Climb the narrow alleyways to the agadir at the top for a sweeping view of palm groves and ochre mountains. Gladiator, Game of Thrones and dozens of other films were shot here.","es":"A media hora de Ouarzazate, el pueblo fortificado de Aït Ben Haddou se alza en el desierto en torres escalonadas de pisé. Sube por sus callejuelas hasta el agadir de la cumbre para disfrutar de una vista panorámica de los palmerales y las montañas ocres. Aquí se rodaron Gladiator, Juego de Tronos y decenas de otras películas.","fr":"À une demi-heure de Ouarzazate, le ksar fortifié d''Aït Ben Haddou s''élève du désert en tours étagées de pisé. Grimpez les ruelles étroites jusqu''à l''agadir au sommet pour une vue panoramique sur les palmeraies et les montagnes ocres. Gladiator, Game of Thrones et des dizaines d''autres films y ont été tournés."}', '["https://upload.wikimedia.org/wikipedia/commons/d/d5/Ksar_A%C3%AFt_Benhaddou%2C_Marocco_%28%D8%A3%D9%8A%D8%AA_%D8%A8%D9%86_%D8%AD%D8%AF%D9%88%D8%8C_%D8%A7%D9%84%D9%85%D8%BA%D8%B1%D8%A8%2C_%E2%B4%B0%E2%B5%A2%E2%B5%9C_%E2%B5%83%E2%B4%B0%E2%B4%B7%E2%B4%B7%E2%B5%93%29.jpg"]', true, 1, null, '["monuments"]', '["historique"]', '31.0470000', '-7.1294000', 'ouarzazate', '{}'), ('bab_doukkala', '{"en":"Bab Doukkala","es":"Bab Doukkala","fr":"Bab Doukkala"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/6/68/Bab_doukkala_IMG_3357.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('bab-aghmat', '{"en":"Bab Aghmat","es":"Bab Aghmat","fr":"Bab Aghmat"}', '2026-06-03 18:34:27.441496+00', '{"en":"A residential and authentic quarter near the eastern ramparts.","es":"Un barrio residencial y auténtico cerca de las murallas orientales.","fr":"Un quartier résidentiel et authentique près des remparts est."}', '{"en":"Located near the eastern gate of the same name, Bab Aghmat is a primarily residential area. It provides a glimpse into the everyday life of Marrakech families, away from the tourist hubs. It is also close to the historic Bab Aghmat cemetery.","es":"Ubicado cerca de la puerta oriental del mismo nombre, Bab Aghmat es un barrio principalmente residencial. Ofrece una visión de la vida cotidiana de las familias de Marrakech, lejos de las zonas turísticas. También está cerca del histórico cementerio de Bab Aghmat.","fr":"Situé près de la porte est du même nom, Bab Aghmat est un quartier principalement résidentiel. Il offre un aperçu de la vie quotidienne des familles de Marrakech, loin des centres touristiques. Il est également proche du cimetière historique de Bab Aghmat."}', '["https://dzuwwfttnigeisicqyto.supabase.co/storage/v1/object/public/quartier_medina/Bab-Ghmat.jpg","https://upload.wikimedia.org/wikipedia/commons/b/b8/Porte_de_ville_sur_les_remparts%2C_personnages_et_%C3%A2nes_sap04_10l00124_p.jpg"]', false, 9, 25, '[]', '["authentique"]', '31.6210000', '-7.9770000', null, '{}'), ('bab-doukkala', '{"en":"Bab Doukkala","es":"Bab Doukkala","fr":"Bab Doukkala"}', '2026-06-03 18:34:27.441496+00', '{"en":"Authentic and local, centered around a lively gate and busy bus station.","es":"Auténtico y local, centrado en torno a una puerta animada y una estación de autobuses concurrida.","fr":"Authentique et local, centré autour d''une porte animée et d''une gare routière."}', '{"en":"Bab Doukkala is a bustling, authentic neighborhood where you can experience the daily life of Marrakchis. It’s home to a major city gate and the main bus station, making it a hub of activity. It offers a less touristy, more local vibe.","es":"Bab Doukkala es un barrio animado y auténtico donde se puede experimentar la vida cotidiana de los marraquechíes. Alberga una de las puertas principales de la ciudad y la estación central de autobuses, lo que lo convierte en un centro de actividad. Ofrece un ambiente menos turístico y más local.","fr":"Bab Doukkala est un quartier animé et authentique où vous pourrez découvrir la vie quotidienne des Marrakchis. Il abrite une porte majeure de la ville et la principale gare routière, ce qui en fait un pôle d''activité. Il offre une ambiance moins touristique et plus locale."}', '["https://dzuwwfttnigeisicqyto.supabase.co/storage/v1/object/public/quartier_medina/bab_doukkala.jpg","https://upload.wikimedia.org/wikipedia/commons/6/68/Bab_doukkala_IMG_3357.jpg"]', false, 4, 20, '[]', '["authentique"]', '31.6330000', '-7.9990000', null, '{}'), ('ben_youssef', '{"en":"Ben Youssef","es":"Ben Youssef","fr":"Ben Youssef"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/3/3a/Coranic_School_%28106589859%29.jpeg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('ben-youssef', '{"en":"Ben Youssef","es":"Ben Youssef","fr":"Ben Youssef"}', '2026-06-03 18:34:27.441496+00', '{"en":"Intellectual and spiritual heart with stunning architectural gems.","es":"Corazón intelectual y espiritual con impresionantes joyas arquitectónicas.","fr":"Cœur intellectuel et spirituel aux joyaux architecturaux éblouissants."}', '{"en":"This district is home to some of Marrakech’s most important historical and architectural sites, including the magnificent Ben Youssef Madrasa and the Marrakech Museum. It feels like a step back in time, with intricate tilework and serene courtyards.","es":"Este distrito alberga algunos de los sitios históricos y arquitectónicos más importantes de Marrakech, incluida la magnífica Madrasa Ben Youssef y el Museo de Marrakech. Se siente como un viaje al pasado, con intrincados mosaicos y patios serenos.","fr":"Ce quartier abrite certains des sites historiques et architecturaux les plus importants de Marrakech, notamment la magnifique Medersa Ben Youssef et le Musée de Marrakech. On a l''impression de remonter le temps, avec des zelliges complexes et des cours sereines."}', '["https://dzuwwfttnigeisicqyto.supabase.co/storage/v1/object/public/quartier_medina/ben_youssef.jpg","https://upload.wikimedia.org/wikipedia/commons/3/3a/Coranic_School_%28106589859%29.jpeg"]', false, 7, 15, '["monuments","musees"]', '["historique"]', '31.6320000', '-7.9870000', null, '{}'), ('dar_el_bacha', '{"en":"⁠Dar El Bacha","es":"⁠Dar El Bacha","fr":"⁠Dar El Bacha"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/0/0b/Dar_el_Bacha.jpg"]', false, null, null, '[]', '[]', null, null, 'marrakech', '{}'), ('dar-el-bacha-mouassine', '{"en":"Dar el Bacha & Mouassine","es":"Dar el Bacha y Mouassine","fr":"Dar el Bacha & Mouassine"}', '2026-06-03 18:34:27.441496+00', '{"en":"Elegant and chic, known for high-end antiques, art galleries, and sophisticated cafes.","es":"Elegante y chic, conocido por sus antigüedades de alta gama, sus galerías de arte y sus cafés sofisticados.","fr":"Élégant et chic, réputé pour ses antiquités haut de gamme, ses galeries d''art et ses cafés sophistiqués."}', '{"en":"This is one of the most sophisticated and stylish districts of the Medina. It is home to the Dar el Bacha Palace (now a museum), chic boutiques, antique shops, and trendy cafes. It’s quieter and more polished than the main souks.","es":"Este es uno de los barrios más sofisticados y elegantes de la Medina. Alberga el Palacio Dar el Bacha (ahora un museo), boutiques chic, tiendas de antigüedades y cafés de moda. Es más tranquilo y refinado que los zocos principales.","fr":"C''est l''un des quartiers les plus sophistiqués et élégants de la Médina. Il abrite le Palais Dar el Bacha (aujourd''hui un musée), des boutiques chics, des antiquaires et des cafés branchés. C''est plus calme et plus raffiné que les souks principaux."}', '["https://upload.wikimedia.org/wikipedia/commons/0/0b/Dar_el_Bacha.jpg","https://upload.wikimedia.org/wikipedia/commons/e/e0/Mouassine_mosque_02.jpg"]', true, 5, 10, '["musees","artisans"]', '["elegant","historique"]', '31.6300000', '-7.9920000', 'marrakech', '{}'), ('derb_dabachi', '{"en":"Derb Dabachi","es":"Derb Dabachi","fr":"Derb Dabachi"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/7/79/Djemaa_el_Fna.jpg"]', false, null, null, '[]', '[]', null, null, 'marrakech', '{}'), ('derb_sidi_bou_amar', '{"en":"Derb Sidi Bou Amar","es":"Derb Sidi Bou Amar","fr":"Derb Sidi Bou Amar"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/3/3b/Saadian_Tombs_1044-HDR.jpg"]', false, null, null, '[]', '[]', null, null, 'marrakech', '{}'), ('derb-dabachi-riad-zitoun', '{"en":"Derb Dabachi & Riad Zitoun","es":"Derb Dabachi & Riad Zitoun","fr":"Derb Dabachi & Riad Zitoun"}', '2026-06-03 18:34:27.441496+00', '{"en":"The bustling heart of the Medina, steps from Jemaa el-Fna.","es":"El corazón animado de la Medina, a pocos pasos de Jemaa el-Fna.","fr":"Le cœur animé de la Médina, à quelques pas de Jemaa el-Fna."}', '{"en":"This area is the vibrant epicenter of Marrakech, leading directly to the famous Jemaa el-Fna square. It’s a sensory explosion of sounds, smells, and colors, packed with shops, street food, and constant activity. Ideal for those who want to be in the middle of the action.","es":"Esta zona es el epicentro vibrante de Marrakech, que conduce directamente a la famosa plaza Jemaa el-Fna. Es una explosión sensorial de sonidos, olores y colores, repleta de tiendas, comida callejera y actividad constante. Ideal para quienes quieren estar en medio de la acción.","fr":"Cette zone est l''épicentre vibrant de Marrakech, menant directement à la célèbre place Jemaa el-Fna. C''est une explosion sensorielle de sons, d''odeurs et de couleurs, regorgeant de boutiques, de cuisine de rue et d''une activité constante. Idéal pour ceux qui veulent être au cœur de l''action."}', '["https://dzuwwfttnigeisicqyto.supabase.co/storage/v1/object/public/quartier_medina/riad_zitoune.jpg","https://upload.wikimedia.org/wikipedia/commons/7/79/Djemaa_el_Fna.jpg"]', true, 1, 5, '["souks","restaurants"]', '["authentique"]', '31.6247000', '-7.9870000', 'marrakech', '{}'), ('desert', '{"en":"Désert","es":"Désert","fr":"Désert"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/8/84/Agafay_desert.jpg"]', false, null, null, '[]', '[]', null, null, 'ouarzazate', '{}'), ('essaouira_exterieurs', '{"en":"Essaouira Exterieurs","es":"Essaouira Exterieurs","fr":"Essaouira Exterieurs"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/b/b6/Morocco_-_Essaouira_Part_2_%2831679848385%29.jpg"]', false, null, null, '[]', '[]', null, null, 'essaouira', '{}'), ('essaouira_medina', '{"en":"Essaouira Medina","es":"Essaouira Medina","fr":"Essaouira Medina"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/c/c0/Medina_of_Essaouira_%28formerly_Mogador%29-113160.jpg"]', false, null, null, '[]', '[]', null, null, 'essaouira', '{}'), ('essaouira-medina', '{"en":"Essaouira Medina","es":"Medina de Essaouira","fr":"Médina d''Essaouira"}', '2026-06-03 18:49:13.327169+00', '{"en":"A UNESCO-listed walled medina of whitewashed houses and bright blue shutters, where artists, surfers and craftsmen cross paths.","es":"Una medina amurallada Patrimonio de la UNESCO, con casas encaladas y postigos azules, donde se cruzan artistas, surfistas y artesanos.","fr":"Une médina fortifiée classée à l''UNESCO, faite de maisons blanches aux volets bleus, où se croisent artistes, surfeurs et artisans."}', '{"en":"Designed by a French engineer in the 18th century, Essaouira''s medina is a perfect grid of bright lanes, art galleries, woodworking ateliers and small riads. Its salt-tinged air, Gnaoua music and laid-back rhythm make it one of Morocco''s most beloved coastal towns.","es":"Diseñada por un ingeniero francés en el siglo XVIII, la medina de Essaouira es una cuadrícula perfecta de callejuelas luminosas, galerías de arte, talleres de marquetería y pequeños riads. Su aire salino, la música gnaoua y su ritmo relajado la convierten en una de las ciudades costeras más queridas de Marruecos.","fr":"Dessinée par un ingénieur français au XVIIIᵉ siècle, la médina d''Essaouira est une grille parfaite de ruelles lumineuses, de galeries d''art, d''ateliers de marqueterie et de petits riads. Son air iodé, sa musique gnaoua et son rythme nonchalant en font l''une des villes côtières les plus aimées du Maroc."}', '["https://upload.wikimedia.org/wikipedia/commons/c/c0/Medina_of_Essaouira_%28formerly_Mogador%29-113160.jpg","https://upload.wikimedia.org/wikipedia/commons/b/b6/Morocco_-_Essaouira_Part_2_%2831679848385%29.jpg"]', true, 1, null, '["souks","artisans"]', '["authentique","elegant"]', '31.5125000', '-9.7700000', 'essaouira', '{}'), ('essaouira-port', '{"en":"Fishing Port","es":"Puerto de pesca","fr":"Port de pêche"}', '2026-06-03 18:49:13.327169+00', '{"en":"A working harbour of bright blue wooden boats, where the day''s catch is auctioned right off the deck.","es":"Un puerto en plena actividad con barcos de madera azul brillante, donde la pesca del día se subasta directamente desde la cubierta.","fr":"Un port toujours actif aux barques en bois bleu vif, où la pêche du jour se vend à la criée directement sur les pontons."}', '{"en":"Essaouira''s port is one of the most photogenic in the country. Wander between piles of nets, swirling seagulls, and stacks of just-landed sardines. Stop at one of the open-air grills for the freshest seafood you''ll ever taste, served on a paper plate facing the sea.","es":"El puerto de Essaouira es uno de los más fotogénicos del país. Pasea entre redes apiladas, gaviotas que revolotean y montones de sardinas recién pescadas. Detente en una de las parrillas al aire libre para probar el marisco más fresco de tu vida, servido en un plato de papel frente al mar.","fr":"Le port d''Essaouira est l''un des plus photogéniques du pays. Promenez-vous au milieu des filets, des mouettes tournoyantes et des cagettes de sardines tout juste débarquées. Arrêtez-vous à l''une des grillades en plein air pour goûter aux poissons les plus frais de votre vie, servis dans une assiette en carton face à l''océan."}', '["https://upload.wikimedia.org/wikipedia/commons/b/b6/Morocco_-_Essaouira_Part_2_%2831679848385%29.jpg"]', true, 3, null, '["restaurants"]', '["authentique"]', '31.5106000', '-9.7747000', 'essaouira', '{}'), ('essaouira-skala', '{"en":"Skala de la Ville","es":"Skala de la Ville","fr":"Skala de la Ville"}', '2026-06-03 18:49:13.327169+00', '{"en":"The legendary sea-facing ramparts lined with bronze cannons and Orson Welles-era cinema history.","es":"Las legendarias murallas frente al mar, jalonadas de cañones de bronce y con historia cinematográfica de la era de Orson Welles.","fr":"Les célèbres remparts face à l''océan, hérissés de canons en bronze, immortalisés par Orson Welles."}', '{"en":"Built atop the old Portuguese fortifications, the Skala offers one of the most cinematic ocean views in Morocco. Walk along the bastion at sunset, watch the Atlantic crash against the rocks, and step into the small marquetry workshops nestled into the ramparts.","es":"Construida sobre las antiguas fortificaciones portuguesas, la Skala ofrece una de las vistas oceánicas más cinematográficas de Marruecos. Pasea por el bastión al atardecer, observa el Atlántico romper contra las rocas y entra en los pequeños talleres de marquetería incrustados en las murallas.","fr":"Bâtie sur les anciennes fortifications portugaises, la Skala offre l''une des vues océaniques les plus cinématographiques du Maroc. Promenez-vous sur le bastion au coucher du soleil, regardez l''Atlantique se briser sur les rochers et poussez la porte des petits ateliers de marqueterie nichés dans les remparts."}', '["https://upload.wikimedia.org/wikipedia/commons/c/c0/Medina_of_Essaouira_%28formerly_Mogador%29-113160.jpg"]', true, 2, null, '["monuments"]', '["historique","calme"]', '31.5142000', '-9.7733000', 'essaouira', '{}'), ('exterior', '{"en":"⁠Exterior","es":"⁠Exterior","fr":"⁠Exterieur"}', '2026-03-13 09:29:54.398923+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/5/5a/Palmeraie_de_Marrakech.JPG"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('gueliz', '{"en":"⁠Gueliz","es":"⁠Gueliz","fr":"⁠Gueliz"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/9/9c/Pavillon_Menarag%C3%A4rten.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('hay_essalam', '{"en":"Hay Essalam","es":"Hay Essalam","fr":"Hay Essalam"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/7/78/In_the_narrow_streets_of_Mellah_of_Marrakech.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('kasbah', '{"en":"Kasbah","es":"Kasbah","fr":"Kasbah"}', '2026-01-24 19:57:11.976102+00', '{"en":"Imperial and majestic, home to royal history and grand landmarks.","es":"Imperial y majestuosa, hogar de la historia real y de grandes monumentos.","fr":"Impérial et majestueux, berceau de l''histoire royale et de grands monuments."}', '{"en":"The Kasbah district is the royal quarter, characterized by its imposing walls and grand gateways. It has a more serene and stately atmosphere compared to the bustling souks. Here you''ll find the Saadian Tombs, the Royal Palace, and beautiful stork-topped ramparts.","es":"El barrio de la Kasbah es el barrio real, caracterizado por sus imponentes muros y grandes puertas. Tiene una atmósfera más serena y majestuosa en comparación con los bulliciosos zocos. Aquí se encuentran las Tumbas Saadíes, el Palacio Real y hermosas murallas coronadas por cigüeñas.","fr":"Le quartier de la Kasbah est le quartier royal, caractérisé par ses murs imposants et ses grandes portes. L''atmosphère y est plus sereine et majestueuse que dans les souks animés. Vous y trouverez les Tombeaux Saadiens, le Palais Royal et de magnifiques remparts coiffés de nids de cigognes."}', '["https://dzuwwfttnigeisicqyto.supabase.co/storage/v1/object/public/quartier_medina/kasbah_marrakech.jpg","https://upload.wikimedia.org/wikipedia/commons/3/3b/Saadian_Tombs_1044-HDR.jpg"]', true, 2, 15, '["monuments"]', '["historique","elegant"]', '31.6180000', '-7.9910000', null, '{}'), ('kennaria', '{"en":"Kennaria","es":"Kennaria","fr":"Kennaria"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/7/79/Djemaa_el_Fna.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('mellah', '{"en":"⁠Mellah","es":"⁠Mellah","fr":"⁠Mellah"}', '2026-01-24 19:57:11.976102+00', '{"en":"A historic area with a unique heritage, vibrant spice souk, and rich stories.","es":"Un barrio histórico con un patrimonio único, un zoco de especias vibrante y muchas historias.","fr":"Un quartier historique au patrimoine unique, avec un souk aux épices vibrant et une histoire riche."}', '{"en":"The old Jewish quarter, the Mellah, offers a distinct atmosphere with its narrow lanes, spice market (souk des épices), and historic synagogues. It''s a place of deep cultural significance and provides a different perspective on Marrakech''s diverse history.","es":"El antiguo barrio judío, el Mellah, ofrece una atmósfera distinta con sus callejuelas estrechas, su mercado de especias (souk de especias) y sus sinagogas históricas. Es un lugar de gran importancia cultural que brinda una perspectiva diferente sobre la diversa historia de Marrakech.","fr":"L''ancien quartier juif, le Mellah, offre une atmosphère distincte avec ses ruelles étroites, son marché aux épices (souk des épices) et ses synagogues historiques. C''est un lieu d''une grande importance culturelle qui offre une perspective différente sur l''histoire diverse de Marrakech."}', '["https://upload.wikimedia.org/wikipedia/commons/7/78/In_the_narrow_streets_of_Mellah_of_Marrakech.jpg"]', false, 3, 18, '["souks","monuments"]', '["historique","authentique"]', '31.6200000', '-7.9840000', null, '{}'), ('montagne', '{"en":"Montagne","es":"Montagne","fr":"Montagne"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/d/d5/Ksar_A%C3%AFt_Benhaddou%2C_Marocco_%28%D8%A3%D9%8A%D8%AA_%D8%A8%D9%86_%D8%AD%D8%AF%D9%88%D8%8C_%D8%A7%D9%84%D9%85%D8%BA%D8%B1%D8%A8%2C_%E2%B4%B0%E2%B5%A2%E2%B5%9C_%E2%B5%83%E2%B4%B0%E2%B4%B7%E2%B4%B7%E2%B5%93%29.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('mouassine', '{"en":"Mouassine","es":"Mouassine","fr":"Mouassine"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/e/e0/Mouassine_mosque_02.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('ouarzazate_exterieurs', '{"en":"Ouarzazate Exterieurs","es":"Ouarzazate Exterieurs","fr":"Ouarzazate Exterieurs"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/3/3b/Ksar_of_Taourirt%2C_Ouarzazate%2C_Morocco_%28%D9%82%D8%B5%D8%A8%D8%A9_%D8%AA%D8%A7%D9%88%D8%B1%D9%8A%D8%B1%D8%AA%2C_%E2%B5%9C%E2%B4%B0%E2%B5%A1%E2%B5%94%E2%B5%89%E2%B5%94%E2%B5%9C%29.jpg"]', false, null, null, '[]', '[]', null, null, 'ouarzazate', '{}'), ('palmeraie', '{"en":"⁠⁠Palmeraie","es":"⁠⁠Palmeraie","fr":"⁠⁠Palmeraie"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/5/5a/Palmeraie_de_Marrakech.JPG"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('rahba_kedina', '{"en":"Rahba Kedina","es":"Rahba Kedina","fr":"Rahba Kedina"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://dzuwwfttnigeisicqyto.supabase.co/storage/v1/object/public/quartier_medina/the_souks.jpg","https://upload.wikimedia.org/wikipedia/commons/7/79/Djemaa_el_Fna.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('riad_laarous', '{"en":"Riad Laarous","es":"Riad Laarous","fr":"Riad Laarous"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/e/e0/Mouassine_mosque_02.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('sidi_ben_slimane', '{"en":"Sidi Ben Slimane","es":"Sidi Ben Slimane","fr":"Sidi Ben Slimane"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://upload.wikimedia.org/wikipedia/commons/e/e0/Mouassine_mosque_02.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}'), ('souks', '{"en":"The Souks","es":"Los zocos","fr":"Les Souks"}', '2026-06-03 18:34:27.441496+00', '{"en":"The commercial heart of the Medina, a labyrinth of artisanal wonders.","es":"El corazón comercial de la Medina, un laberinto de maravillas artesanales.","fr":"Le cœur commercial de la Médina, un labyrinthe de merveilles artisanales."}', '{"en":"The famous Souks of Marrakech are a sprawling maze of covered alleyways filled with everything from leather goods and lanterns to spices and slippers. It’s a must-visit for shopping and soaking up the vibrant, chaotic atmosphere. Each souk is traditionally dedicated to one craft.","es":"Los famosos zocos de Marrakech son un extenso laberinto de callejones cubiertos repletos de todo, desde artículos de cuero y faroles hasta especias y babuchas. Es una visita imprescindible para ir de compras y empaparse del ambiente vibrante y caótico. Cada zoco está tradicionalmente dedicado a un oficio.","fr":"Les célèbres souks de Marrakech sont un dédale tentaculaire de ruelles couvertes regorgeant de tout, des articles en cuir et des lanternes aux épices et aux babouches. C''est une visite incontournable pour le shopping et pour s''imprégner de l''atmosphère vibrante et chaotique. Chaque souk est traditionnellement dédié à un corps de métier."}', '["https://dzuwwfttnigeisicqyto.supabase.co/storage/v1/object/public/quartier_medina/the_souks.jpg"]', true, 6, 8, '["souks","artisans"]', '["authentique"]', '31.6280000', '-7.9890000', null, '{}'), ('taourirt-kasbah', '{"en":"Taourirt Kasbah","es":"Kasbah de Taourirt","fr":"Kasbah de Taourirt"}', '2026-06-03 18:49:13.327169+00', '{"en":"The fortified residence of the Glaoui pashas at the heart of Ouarzazate.","es":"La residencia fortificada de los pashás Glaoui en el corazón de Ouarzazate.","fr":"La résidence fortifiée des pachas Glaoui au cœur de Ouarzazate."}', '{"en":"Right inside Ouarzazate, the Taourirt Kasbah is a labyrinth of ornate reception rooms, harem quarters and rooftop terraces that once housed one of the most powerful families of southern Morocco. Its richly painted ceilings and zellige walls give a glimpse of pre-Independence Berber aristocracy.","es":"En el mismo Ouarzazate, la Kasbah de Taourirt es un laberinto de suntuosas salas de recepción, aposentos del harén y terrazas que albergaron a una de las familias más poderosas del sur de Marruecos. Sus techos pintados y sus paredes de zellige ofrecen una visión de la aristocracia bereber anterior a la Independencia.","fr":"En plein cœur de Ouarzazate, la Kasbah de Taourirt est un dédale de salons d''apparat, d''appartements de harem et de terrasses qui ont abrité l''une des familles les plus puissantes du sud marocain. Ses plafonds peints et ses murs de zellige offrent un aperçu de l''aristocratie berbère pré-indépendance."}', '["https://upload.wikimedia.org/wikipedia/commons/3/3b/Ksar_of_Taourirt%2C_Ouarzazate%2C_Morocco_%28%D9%82%D8%B5%D8%A8%D8%A9_%D8%AA%D8%A7%D9%88%D8%B1%D9%8A%D8%B1%D8%AA%2C_%E2%B5%9C%E2%B4%B0%E2%B5%A1%E2%B5%94%E2%B5%89%E2%B5%94%E2%B5%9C%29.jpg"]', true, 2, null, '["monuments","musees"]', '["historique","elegant"]', '30.9189000', '-6.8967000', 'ouarzazate', '{}'), ('vallee-draa', '{"en":"Draâ Valley","es":"Valle del Draa","fr":"Vallée du Draâ"}', '2026-06-03 18:49:13.327169+00', '{"en":"A 200-km ribbon of palm groves, mudbrick villages and old kasbahs winding from Ouarzazate to the dunes of Zagora.","es":"Una franja de 200 km de palmerales, pueblos de adobe y antiguas kasbahs que serpentea desde Ouarzazate hasta las dunas de Zagora.","fr":"Un ruban de 200 km de palmeraies, de villages en pisé et de vieilles kasbahs serpentant de Ouarzazate aux dunes de Zagora."}', '{"en":"Following the Draâ River south of Ouarzazate, this valley is one of Morocco''s great scenic drives. Stop in Agdz, Tamnougalt or Zagora to wander palm groves still tended by berber families, sleep in a restored kasbah, and end the journey on a camel into the Sahara dunes of Tinfou.","es":"Siguiendo el río Draa al sur de Ouarzazate, este valle es una de las rutas escénicas más impresionantes de Marruecos. Detente en Agdz, Tamnougalt o Zagora para recorrer palmerales aún cuidados por familias bereberes, dormir en una kasbah restaurada y terminar el viaje a camello en las dunas saharianas de Tinfou.","fr":"Suivant l''oued Draâ au sud de Ouarzazate, cette vallée offre l''une des plus belles routes panoramiques du Maroc. Arrêtez-vous à Agdz, Tamnougalt ou Zagora pour parcourir des palmeraies encore cultivées par les familles berbères, dormez dans une kasbah restaurée et terminez le périple à dos de chameau dans les dunes sahariennes de Tinfou."}', '["https://upload.wikimedia.org/wikipedia/commons/a/ae/Draa_River.jpg"]', true, 3, null, '["monuments"]', '["authentique","calme"]', '30.3500000', '-6.4500000', 'ouarzazate', '{}'), ('zaouia-sidi-bel-abbes', '{"en":"Zaouia of Sidi Bel Abbès","es":"Zaouia de Sidi Bel Abbès","fr":"Zaouia de Sidi Bel Abbès"}', '2026-06-03 18:34:27.441496+00', '{"en":"A spiritual and less-touristy area, important for local pilgrims.","es":"Una zona espiritual y menos turística, importante para los peregrinos locales.","fr":"Une zone spirituelle et moins touristique, importante pour les pèlerins locaux."}', '{"en":"This neighborhood is centered around the mausoleum of Sidi Bel Abbès, one of the seven saints of Marrakech. It holds deep spiritual significance for locals and offers a more tranquil, off-the-beaten-path experience. The area is not accessible to non-muslims but its surroundings are full of life.","es":"Este barrio se centra en torno al mausoleo de Sidi Bel Abbès, uno de los siete santos de Marrakech. Tiene una profunda importancia espiritual para los habitantes y ofrece una experiencia más tranquila y fuera de lo común. La zona no es accesible a los no musulmanes, pero sus alrededores están llenos de vida.","fr":"Ce quartier est centré autour du mausolée de Sidi Bel Abbès, l''un des sept saints de Marrakech. Il revêt une profonde signification spirituelle pour les habitants et offre une expérience plus tranquille et hors des sentiers battus. Le site n''est pas accessible aux non-musulmans mais ses alentours sont pleins de vie."}', '["https://dzuwwfttnigeisicqyto.supabase.co/storage/v1/object/public/quartier_medina/zaouia.jpg"]', false, 8, 22, '[]', '["authentique"]', '31.6390000', '-7.9920000', null, '{}'), ('zitoun', '{"en":"Zitoun","es":"Zitoun","fr":"Zitoun"}', '2026-01-24 19:57:11.976102+00', null, null, '["https://dzuwwfttnigeisicqyto.supabase.co/storage/v1/object/public/quartier_medina/riad_zitoune.jpg"]', false, null, null, '[]', '[]', null, null, null, '{}')
